import{_ as n,o as a,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Фунарг-проблема","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-function/closures/funarg.md","filePath":"wiki/dev-commit/js/js-function/closures/funarg.md"}'),p={name:"wiki/dev-commit/js/js-function/closures/funarg.md"};function e(t,s,c,r,i,y){return a(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="фунарг-проблема" tabindex="-1">Фунарг-проблема <a class="header-anchor" href="#фунарг-проблема" aria-label="Permalink to &quot;Фунарг-проблема&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="http://dmitrysoshnikov.com/ecmascript/ru-chapter-6-closures/#funarg-problema" target="_blank" rel="noreferrer">http://dmitrysoshnikov.com/ecmascript/ru-chapter-6-closures/#funarg-problema</a></p></div><h2 id="фунарг" tabindex="-1">Фунарг <a class="header-anchor" href="#фунарг" aria-label="Permalink to &quot;Фунарг&quot;">​</a></h2><ul><li><strong>Фунарг</strong> - сокращение от «функциональный аргумент»</li><li>В стековых языках программирования, локальные переменные функции хранятся в стеке, который наполняется новыми элементами при выполнении функции. При выходе из функции, эти переменные удаляются из стека</li><li>Ограничения для использования функций при &quot;возврате из функции&quot; и при &quot;передаче в виде аргумента&quot;</li><li>Решение: Использование замыканий</li></ul><h2 id="виды" tabindex="-1">Виды <a class="header-anchor" href="#виды" aria-label="Permalink to &quot;Виды&quot;">​</a></h2><ul><li><strong>Проблема восходящего фунарга</strong> (upward funarg) - возникает при возврате функции из некоторой функции</li><li><strong>Проблема нисходящего фунарга</strong> (downward funarg) - возникает при передаче функции в качестве параметра некоторой функции</li></ul><h2 id="проблема-1-свободные-переменные" tabindex="-1">Проблема #1: Свободные переменные <a class="header-anchor" href="#проблема-1-свободные-переменные" aria-label="Permalink to &quot;Проблема #1: Свободные переменные&quot;">​</a></h2><ul><li>Наиболее характерно Фунарг-проблема проявляется при использовании в функции свободных переменных</li><li><strong>Свободная переменная</strong> (Free variable) - переменная, используемая функцией, но не являющаяся ни параметром, ни локальной переменной этой функции</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> testFn</span><span style="color:#383A42;">() {</span></span>
<span class="line"><span style="color:#A626A4;">	const</span><span style="color:#986801;"> localVar</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 10</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">	function</span><span style="color:#4078F2;"> innerFn</span><span style="color:#383A42;">(innerParam) {</span></span>
<span class="line"><span style="color:#4078F2;">		alert</span><span style="color:#383A42;">(innerParam </span><span style="color:#0184BC;">+</span><span style="color:#383A42;"> localVar);</span></span>
<span class="line"><span style="color:#383A42;">	}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">	return</span><span style="color:#383A42;"> innerFn;</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"><span style="color:#383A42;"> </span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> someFn</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> testFn</span><span style="color:#383A42;">();</span></span>
<span class="line"><span style="color:#4078F2;">someFn</span><span style="color:#383A42;">(</span><span style="color:#986801;">20</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// 30</span></span></code></pre></div><ul><li>В данном случае, для функции innerFn свободной переменной является localVar</li><li>Если бы в данной системе использовалась стековая реализация для хранения локальных переменных, это означало бы, что по завершении функции testFn, все её локальные переменные должны были бы удалиться из стека, что привело бы к ошибке при вызове функции innerFn снаружи посредством someFn</li><li>В данном случае, при стековой организации, и сам возврат функции innerFn был бы невозможен, т.к. innerFn так же является локальной функцией для функции testFn и будет удалена по завершению testFn</li></ul><h2 id="проблема-2-передача-функции-в-качестве-аргумента" tabindex="-1">Проблема #2: Передача функции в качестве аргумента <a class="header-anchor" href="#проблема-2-передача-функции-в-качестве-аргумента" aria-label="Permalink to &quot;Проблема #2: Передача функции в качестве аргумента&quot;">​</a></h2><ul><li>Проблема возникает при организации системы с динамической областью видимости</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 10</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> someFn</span><span style="color:#383A42;">() {</span></span>
<span class="line"><span style="color:#4078F2;">	alert</span><span style="color:#383A42;">(x);</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#4078F2;">someFn</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - и при статической и при динамической Scope</span></span>
<span class="line"><span style="color:#383A42;"> </span></span>
<span class="line"><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;"> () {</span></span>
<span class="line"><span style="color:#A626A4;">	const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 20</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#4078F2;">	someFn</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - при статической, 20 - при динамической Scope</span></span>
<span class="line"><span style="color:#383A42;">})();</span></span>
<span class="line"><span style="color:#383A42;"> </span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// аналогично, при передаче someFn</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// в качестве параметра</span></span>
<span class="line"><span style="color:#383A42;"> </span></span>
<span class="line"><span style="color:#383A42;">(</span><span style="color:#A626A4;">function</span><span style="color:#383A42;"> (funArg) {</span></span>
<span class="line"><span style="color:#A626A4;">	const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 30</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#4078F2;">	funArg</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// 10 - при статической, 30 - при динамической Scope</span></span>
<span class="line"><span style="color:#383A42;">})(someFn);</span></span></code></pre></div><ul><li>При организации системы с динамической областью видимости, разрешение имени переменной осуществляется в пределах динамического (активного) стека переменных (свободная переменная ищется в динамической цепи вызова, а не в статической цепи создания функции), что может привести к неоднозначности</li><li>При этом, даже, если x будет определена (в отличии от предыдущего примера, где локальные переменные удалились бы из стека и были бы не определены), возникнет вопрос, какое из значений x (точнее, x из какого контекста, какой области видимости) должно использоваться в различных вызовах функции someFn?</li></ul>`,14)])])}const d=n(p,[["render",e]]);export{u as __pageData,d as default};
